<script setup lang="ts">
/**
 * A date *field* with segmented entry and a calendar popup (`design/components/date-picker.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/popover'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  agentDate,
  agentDateTime,
  agentMember,
  anchorProps,
  calendarDateOf,
  dateFieldDraft,
  dateFieldValue,
  dateOutOfBounds,
  eraseSegment,
  fieldSegments,
  stepSegment,
  syncTriggerAnchor,
  typeIntoSegment,
  useDirection,
  useMediaQuery,
  type CalendarDateTime,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/date-picker.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Button from './Button.vue'
import Calendar, { type CalendarDate, type CalendarMessages } from './Calendar.vue'

export type DatePickerMessages = CalendarMessages & {
  showCalendar: string
  clear: string
  chooseDate: string
  empty?: string
}

export interface DatePickerProps {
  ariaDescribedby?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * Input's clear button. Clearing returns the segments to their placeholders.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: CalendarDate | null | CalendarDateTime
  disabled?: boolean
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  granularity?: 'day' | 'hour' | 'minute'
  id?: string
  invalid?: boolean
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Orders the segments as well as naming the months.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: DatePickerMessages
  minValue?: CalendarDate
  /**
   * Serializes ISO-8601, at the granularity.
   */
  name?: string
  /**
   * `'auto'` shows the popup as a sheet below `30rem` (the conventions' sheet presentation),
   * with Calendar unchanged inside it. `'popover'` keeps the popover at every width. There is no
   * always-sheet value (`docs/layout.md`). The segments stay the primary input at every width,
   * and the field itself never becomes a sheet.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * `CalendarDateTime`: the same package's datetime type, without a time zone, never a JS `Date`
   * (Calendar's law). The value type follows the granularity, and React Aria enforces the match
   * at runtime instead of inventing a midnight time.
   */
  value?: CalendarDate | null | CalendarDateTime
}

defineOptions({ name: 'DatePicker', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<DatePickerProps>(), {
  ariaRequired: undefined,
  clearable: false,
  defaultOpen: undefined,
  disabled: false,
  granularity: 'day',
  invalid: false,
  isDateUnavailable: undefined,
  presentation: 'auto',
  size: 'md',
})
const emit = defineEmits<{ change: [value: CalendarDate | null | CalendarDateTime | null] }>()
const uid = useId()
const browserLanguage = ref(undefined as string | undefined)
const draft = ref(
  dateFieldDraft(props.value !== undefined ? props.value : props.defaultValue, {
    locale: props.locale ?? browserLanguage.value ?? 'en-US',
    parts:
      props.granularity === 'minute'
        ? (['year', 'month', 'day', 'hour', 'minute'] as const)
        : props.granularity === 'hour'
          ? (['year', 'month', 'day', 'hour'] as const)
          : (['year', 'month', 'day'] as const),
  }),
)
const typed = ref('')
const reported = ref(
  (props.value !== undefined ? props.value : props.defaultValue)?.toString() ?? '',
)
const anchor = useTemplateRef<HTMLElement>('anchor')
const field = useTemplateRef<HTMLElement>('field')
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const phone = useMediaQuery('phone')
const say = computed(() => ({
  empty: 'Empty',
  ...(props.messages ?? {
    previousMonth: 'Previous month',
    nextMonth: 'Next month',
    showCalendar: 'Show calendar',
    clear: 'Clear',
    chooseDate: 'Choose a date',
  }),
}))
const language = computed(() => props.locale ?? browserLanguage.value ?? 'en-US')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const fieldOptions = computed(() => ({
  locale: language.value,
  parts:
    props.granularity === 'minute'
      ? (['year', 'month', 'day', 'hour', 'minute'] as const)
      : props.granularity === 'hour'
        ? (['year', 'month', 'day', 'hour'] as const)
        : (['year', 'month', 'day'] as const),
}))
const segments = computed(() => fieldSegments(draft.value, fieldOptions.value))
const kept = computed(() => (props.value !== undefined ? props.value : props.defaultValue) ?? null)
const current = computed(() => dateFieldValue(draft.value, fieldOptions.value, kept.value))
const fieldInvalid = computed(
  () =>
    props.invalid ||
    dateOutOfBounds(current.value, {
      min: props.minValue,
      max: props.maxValue,
      unavailable: props.isDateUnavailable,
    }),
)
const showClear = computed(() => props.clearable && current.value !== null && !props.disabled)
const commit = computed(() => (next: ReturnType<typeof dateFieldDraft>): void => {
  draft.value = next
  const after = dateFieldValue(next, fieldOptions.value, kept.value)
  const text = after?.toString() ?? ''
  if (text !== reported.value) {
    reported.value = text
    emit('change', after)
  }
})
const clear = computed(() => (): void => {
  commit.value({})
  field.value?.querySelector<HTMLElement>('[data-segment]')?.focus()
})
const segmentName = computed(() => (type: string): string => {
  try {
    return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
  } catch {
    return type
  }
})
const moveSegment = computed(() => (from: EventTarget | null, step: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + step]?.focus()
})
const segmentInput = computed(
  () =>
    (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
      event.preventDefault()
      if (segment.type === 'literal' || !!props.disabled) return
      const data = (event as InputEvent).data ?? ''
      for (const key of data) {
        const next = typeIntoSegment(
          draft.value,
          segment.type,
          typed.value,
          key,
          fieldOptions.value,
        )
        typed.value = next.typed
        commit.value(next.draft)
        if (next.advance) {
          moveSegment.value(event.currentTarget, 1)
          break
        }
      }
    },
)
const documentDirection = useDirection(() => field.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultOpen: props.defaultOpen,
    modal: sheeting.value,
    positioning: { placement: 'bottom-end' as const, offset: { mainAxis: 2 } },
    ids: props.id === undefined ? undefined : { anchor: props.id },
    initialFocusEl: () =>
      (sheetPanel.value ?? panel.value)?.querySelector<HTMLElement>('[tabindex="0"]') ?? null,
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const choose = computed(() => (date: CalendarDate | null): void => {
  if (date === null) return
  commit.value({ ...draft.value, year: date.year, month: date.month, day: date.day })
  api.value.setOpen(false)
})
const segmentKeys = computed(
  () =>
    (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
      if (segment.type === 'literal') return
      if (event.altKey && event.key === 'ArrowDown') {
        event.preventDefault()
        if (!props.disabled) api.value.setOpen(true)
        return
      }
      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        event.preventDefault()
        typed.value = ''
        moveSegment.value(
          event.currentTarget,
          (event.key === 'ArrowRight') ===
            (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
            ? 1
            : -1,
        )
        return
      }
      if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
      const editable = !props.disabled
      if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
        event.preventDefault()
        typed.value = ''
        if (editable)
          commit.value(
            stepSegment(
              draft.value,
              segment.type,
              event.key === 'ArrowUp' ? 1 : -1,
              fieldOptions.value,
            ),
          )
        return
      }
      if (event.key === 'Backspace' || event.key === 'Delete') {
        event.preventDefault()
        typed.value = ''
        if (!editable) return
        if (draft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
        else commit.value(eraseSegment(draft.value, segment.type, fieldOptions.value))
        return
      }
      if (event.key.length !== 1) return
      event.preventDefault()
      if (editable)
        ((key: string): void => {
          const next = typeIntoSegment(
            draft.value,
            segment.type,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          commit.value(next.draft)
          if (next.advance) moveSegment.value(event.currentTarget, 1)
        })(event.key)
    },
)
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
const effect1 = () => {
  ;((browserLanguage.value = globalThis.navigator?.language),
    props.locale === undefined &&
      (draft.value = dateFieldDraft(props.value !== undefined ? props.value : props.defaultValue, {
        locale: props.locale ?? browserLanguage.value ?? 'en-US',
        parts:
          props.granularity === 'minute'
            ? (['year', 'month', 'day', 'hour', 'minute'] as const)
            : props.granularity === 'hour'
              ? (['year', 'month', 'day', 'hour'] as const)
              : (['year', 'month', 'day'] as const),
      })))
}
onMounted(effect1)
const effect2 = () => {
  syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
}
onMounted(effect2)
watch(() => api.value.open, effect2, { flush: 'post' })
const effect3 = () => {
  props.value !== undefined &&
    (props.value !== null || current.value !== null) &&
    ((draft.value = dateFieldDraft(props.value, fieldOptions.value)),
    (reported.value = props.value?.toString() ?? ''))
}
watch(() => props.value, effect3, { flush: 'post' })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'DatePicker',
    element: () => field.value,
    state: () => ({
      value: current.value?.toString() ?? '',
      open: api.value.open,
      disabled: props.disabled,
      invalid: fieldInvalid.value,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            const bounds = {
              min: props.minValue,
              max: props.maxValue,
              unavailable: props.isDateUnavailable,
            }
            commit.value(
              dateFieldDraft(
                props.granularity === 'day'
                  ? agentDate(value, bounds)
                  : agentDateTime(value, bounds, props.granularity),
                fieldOptions.value,
              ),
            )
          })(),
      },
      clear: () => commit.value({}),
      open: () => api.value.setOpen(true),
      close: () => api.value.setOpen(false),
    },
    withholds: () => [field.value, sheetPanel.value ?? panel.value],
  })
  release4 = () => {
    ran()
  }
}
onMounted(effect4)
onBeforeUnmount(() => release4?.())
</script>

<template>
  <div
    ref="field"
    v-bind="api.getAnchorProps()"
    :class="styles.field"
    role="group"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-disabled="disabled ? 'true' : undefined"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="fieldInvalid ? '' : undefined"
    :data-state="api.open ? 'open' : 'closed'"
    data-member="date-picker"
  >
    <!-- segments -->
    <div :class="styles.segments" :data-size="size">
      <template v-for="(segment, at) in segments" :key="`date-${segment.type}-${at}`">
        <!-- separator -->
        <span v-if="segment.type === 'literal'" :class="styles.separator" aria-hidden="true">
          {{ segment.text }}
        </span>
        <!-- segment -->
        <div
          v-else
          :class="styles.segment"
          role="spinbutton"
          :id="`${uid}-date-${segment.type}`"
          :aria-label="segmentName(segment.type)"
          :aria-labelledby="
            ariaLabelledby ? `${ariaLabelledby} ${uid}-date-${segment.type}` : undefined
          "
          :aria-describedby="ariaDescribedby"
          :aria-valuenow="segment.placeholder ? undefined : segment.value"
          :aria-valuemin="segment.min"
          :aria-valuemax="segment.max"
          :aria-valuetext="segment.placeholder ? say.empty : segment.text"
          :aria-required="ariaRequired ? 'true' : undefined"
          :aria-disabled="disabled ? 'true' : undefined"
          :aria-invalid="fieldInvalid ? 'true' : undefined"
          :contenteditable="!disabled ? 'true' : undefined"
          :inputmode="segment.type === 'dayPeriod' ? undefined : 'numeric'"
          spellcheck="false"
          :tabindex="disabled ? undefined : '0'"
          :data-segment="segment.type"
          :data-placeholder="segment.placeholder ? '' : undefined"
          :data-disabled="disabled ? '' : undefined"
          @focus="typed = ''"
          @keydown="segmentKeys($event, segment)"
          @beforeinput="segmentInput($event, segment)"
        >
          {{ segment.text }}
        </div>
      </template>
    </div>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="current?.toString() ?? ''"
      :disabled="disabled ? true : undefined"
    />
    <!-- clear -->
    <button
      v-if="showClear"
      :class="styles.clear"
      type="button"
      :aria-label="say.clear"
      @click="clear()"
    >
      <Icon name="clear" :size="size" />
    </button>
    <!-- trigger -->
    <span ref="anchor" v-bind="anchorProps(api.getTriggerProps())" :class="triggerAnchor.anchor">
      <Button
        variant="ghost"
        tone="neutral"
        :size="size"
        :iconOnly="true"
        icon="calendar"
        :label="say.showCalendar"
        :disabled="disabled"
      />
    </span>
  </div>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.content"
        :style="{ '--radix-popover-content-transform-origin': 'var(--transform-origin)' }"
        :hidden="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        :aria-label="say.chooseDate"
        data-member="date-picker"
      >
        <Calendar
          :value="current === null ? null : calendarDateOf(current)"
          :minValue="minValue"
          :maxValue="maxValue"
          :isDateUnavailable="isDateUnavailable"
          :locale="language"
          :firstDayOfWeek="firstDayOfWeek"
          :messages="say"
          :aria-label="say.chooseDate"
          @change="choose($event)"
        />
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        v-bind="api.getContentProps()"
        :class="sheet.panel"
        :hidden="undefined"
        :aria-labelledby="undefined"
        :aria-describedby="undefined"
        :aria-label="say.chooseDate"
        aria-modal="true"
        data-presentation="sheet"
      >
        <!-- sheetBody -->
        <div :class="styles.sheetBody" data-member="date-picker">
          <Calendar
            :value="current === null ? null : calendarDateOf(current)"
            :minValue="minValue"
            :maxValue="maxValue"
            :isDateUnavailable="isDateUnavailable"
            :locale="language"
            :firstDayOfWeek="firstDayOfWeek"
            :messages="say"
            :aria-label="say.chooseDate"
            @change="choose($event)"
          />
        </div>
      </div>
    </div>
  </Teleport>
</template>
